  'node:crypto':{createHash},
  './.github/ci/staging-build-install.mjs':{readPrivateInstall:id=>id===oldId?{grant:x.oldGrant,authorizationSha256:x.oldHash,directory:'/old'}:{grant:x.grant,authorizationSha256:x.newHash,directory:'/new'}},
